def verify_graph(edges, n_vertices=15, min_edges=19):
    # Check number of vertices
    vertices = set()
    for u, v in edges:
        vertices.add(u)
        vertices.add(v)
        assert 0 <= u < v < n_vertices, f"Invalid edge ({u}, {v})"

    print(f"Number of vertices: {len(vertices)}")
    print(f"Number of edges: {len(edges)}")

    # Check bipartite (2-colorable)
    from collections import deque
    color = {}
    is_bipartite = True
    for start in range(n_vertices):
        if start in color:
            continue
        color[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in range(n_vertices):
                if (u, v) in edges or (v, u) in edges:
                    if v not in color:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        is_bipartite = False
                        break
            if not is_bipartite:
                break
        if not is_bipartite:
            break

    print(f"Is bipartite (2-colorable): {is_bipartite}")

    # Check girth >= 4 (no triangles)
    # Build adjacency list
    adj = {i: set() for i in range(n_vertices)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    has_triangle = False
    for u in range(n_vertices):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        has_triangle = True
                        print(f"Triangle found: ({u}, {v}, {w})")
                        break
                if has_triangle:
                    break
            if has_triangle:
                break
        if has_triangle:
            break

    print(f"Has triangle (girth < 4): {has_triangle}")
    print(f"Girth >= 4: {not has_triangle}")

    # Check edge count
    print(f"Has at least {min_edges} edges: {len(edges) >= min_edges}")

    return is_bipartite and not has_triangle and len(edges) >= min_edges

